import {limitCover} from './limit/art.js';
import {gladiatorCover} from './gladiator-art.js';
import {mathCover} from './math-art.js';
import {spellingCover} from './spelling-art.js';
import {airSliceDemoArt} from './air-slice-art.js';
import {mediaCoverArt} from './media-art.js';
import {coverArt} from './premium-art.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Content stays inside the launch dialog: the secret game is never listed elsewhere.
export const GAME_INSTRUCTIONS={
 limit:{title:'Project Limit Break',objective:'Restore three lanterns, defeat three enchanted sentinels, use the Wayfarer Gate lever and bring every explorer through.',controls:'Xbox: left stick moves, right stick looks; A jumps, X strikes, B dodges, Y interacts, RT pulses, RB runs. LB recenters, Menu pauses, View opens help. Menus: D-pad/stick, A confirm, B back. Keyboard P1: WASD, Shift run, Space jump, E use, F strike, R pulse, C dodge. P2: arrows, Numpad 1 run, 0 jump, Enter use, 2 strike, 3 pulse, 4 dodge. Touch: independent sticks and six labeled buttons. Tap ground to walk; right-drag or Camera mode orbits.',win:'Approach each lantern and press Interact. Cross deep water at the bridge. Sentinels pursue and attack; red rings warn of melee strikes. Strike nearby or pulse at a visible target. After three lanterns and three victories, Interact at the gate lever, wait for the door to rise and walk through.',score:'Finish for 1800 points, minus 100 per water recovery and 150 per combat recovery, plus two points per second remaining from a 240-second bonus. Minimum completed score: 300. No failure timer. Combat scores have a separate edition; older scores remain. Benchmarks earn no points.',rules:'Solid scenery, people and moving crates block movement; leaves and grass do not. Jump onto low props or push crates. Pulses stop at obstacles; no friendly fire. Normal hits preserve attacks. Dodge briefly avoids damage. Zero health returns you to your last checkpoint with a short shield. Lanterns heal. Unlimited retries. Pause freezes the world. Forest Baseline is automatic; pause, resize or tab hiding cancels it.',duo:'P1 and P2 play simultaneously, sharing objectives and camera range, with separate health and cooldowns. Both must reach the exit. A fallen teammate recovers independently. Two standard controllers join in connection order; disconnection pauses play. Controller + keyboard/touch also works. Mouse tap-to-walk selects P1/P2 or Tab; physical multitouch depends on your device.',gestures:['drag','tap','look']},

 gladiator:{title:'Gladiator Arena',objective:'Create a gladiator, buy individual equipment upgrades, and defeat seven tournament champions. Or challenge a friend in a local duel.',controls:'Tap a circular action button on your turn. Walk or jump to control distance; quick, normal and power attacks trade accuracy, damage and energy. Charge closes a gap. Shove pushes, taunt drains energy, defend blocks, and rest recovers energy.',win:'Reduce the opponent’s red health to zero or push them past an arena edge. Career tournaments require the displayed level, wins and previous laurel. Duels finish one round, or the first to two or three round wins.',score:'Career victories earn gold, XP and arcade points. Train attributes after leveling up. Charisma improves gold rewards and prices. Buy and equip owned gear separately in each slot.',rules:'Wait for each animation to finish. Actions require energy and range; disabled buttons are unavailable. Armor absorbs damage before health. Hard defeats cost 8% of unspent gold; all equipment, XP and laurels are kept. Rest gives the opponent a turn.',duo:'Player 1 and Player 2 alternate every action. Pass the screen and press Ready. Choose different arcade profiles and saved gladiators. Duels use equally leveled copies and balanced equipment, so neither career is overwritten. Best of 3 needs two round wins; Best of 5 needs three.',gestures:['tap','wait','look']},
 math:{title:'Math Quest',objective:'Choose your school grade and subject category, explore mathematics worlds and solve varied challenges. Use the large notebook to show your thinking, then enter a final answer separately.',controls:'Write with finger, stylus or mouse. Choose pen, eraser, shapes, ruler, colors and paper. Move Paper pans a larger sheet; zoom and Fraction Space give extra room. Use the keypad, choices, draggable tiles, number line or clock controls for answers.',win:'Finish the selected questions. Adventure stages need 70% correct; three stages open the next world. Practice and Homework Helper let you learn at your own pace. Speed Challenge’s timer can be disabled in setup.',score:'Correct answers earn 100 base points, 25 without help, plus a small within-grade difficulty bonus. Grades have equal point values. Hints and Show Me How teach steps; handwriting is never scored. Homework Helper earns learning progress without competitive points.',rules:'Check Answer gives feedback while your writing stays visible. Next advances only when you are ready. Fractions may be equivalent; coordinates use x,y and clocks use H:MM. New Adaptive skills start at the standard grade level, ease after mistakes, and advance through independent answers within your grade and skill. Pause stops the timer.',duo:'Take-turns alternates after every question, with the same selected number of questions for each player and separate grades, writing, scores and progress. The next question stays hidden until Ready. Co-op shares one notebook, combines stars and works toward a shared goal, using each teammate’s grade in turn.',gestures:['draw','tap','drag']},

 spelling:{title:'Spelling Adventure',objective:'Hear a word, practice it on the whiteboard, then type your answer and press Submit to score points.',controls:'Hear Word repeats pronunciation. Use the touchscreen keys or a physical keyboard. Pen, eraser, undo and clear affect only handwriting. In Letter Builder, tap or drag tiles; in Missing Letters, type only the gaps.',win:'Bee, Builder and Missing Letters finish the chosen word count. Sprint lasts the chosen time, or a word count when untimed. Survival ends after three mistakes or when the word trail is exhausted.',score:'Correct answers: 100 points; no hint: 25 extra. Streaks of 3, 5 and 10 add 50, 100 and 250. Sprint adds up to 20 speed points. Incorrect answers show the correct spelling and letter feedback; press Next when ready.',rules:'Drawings never submit answers. Writing stays between words unless Auto-Clear is ON. A mastered word needs three correct answers without hints across separate adventures. Recent words wait their turn. Speech uses installed browser voices; definitions provide a quiet fallback.',duo:'Player 1 and Player 2 can choose different named word pools. Split-screen runs at the same time with separate keys and boards; take-turns freezes the next player’s clock. Co-op alternates prompts on a shared board and combines points and team streaks. Correct words have equal base points.',gestures:['listen','draw','tap']},
 air:{title:'Air Slice',objective:'Stand in front of the camera and swipe either hand through flying fruit. Make big, juicy combinations!',controls:'After GOT IT, enable the webcam. Lower both arms, then raise them to calibrate. Sweep through fruit; still hands do not slice. Touch/mouse mode uses held drags.',win:'Classic: keep three lives. Arcade and Frenzy: score in 60 seconds. Zen: relax without bombs or miss penalties; unlimited Zen ends when you press Finish.',score:'Fruit earns 10 points, golden fruit 50. Multiple fruit in one moving swing multiply points. Rainbow doubles points; Freeze slows fruit; Storm launches more. Giant melons need three separate strikes.',rules:'Avoid the clearly marked bombs: Classic loses a life; timed modes lose 30 points. Tracking loss pauses play. Background Removal ON places you in the animated world; OFF shows your room. Toggle in camera setup, the BG button or settings without resetting scores. While ON, outline gaps hold the last cutout briefly, then show only virtual scenery. Sustained failures stop outline work; choose OFF for the original camera or OFF/ON to retry. Camera processing stays local; no microphone or footage recording.',duo:'Player 1 starts on the blue left; Player 2 on the orange right. Both hands work for both players. Versus: first slicer owns a fruit. Co-op shares points/lives; team fruit needs both players. Alternating mouse gives equivalent turns.',gestures:['look','swipe','drag']},
 funny:{title:'Funny Face Studio',objective:'Turn your real camera image into funny photos and videos with face-following distortion.',controls:'Enable your camera, then select up to three distortions and an animated lens. Drag stickers; use two fingers to resize/rotate. Tap Photo or Record Video.',win:'Create freely. Pose challenges use tracked expressions; two-face challenges use the left and right faces.',score:'Creative photos and videos are unranked. Pose challenges score matched expressions and completion time.',rules:'Camera/microphone start only when you enable them. Capture records the visible composite. Video edits must render before export. Media stays local; save before leaving.',duo:'Create together with up to two tracked faces. Player 1 is the left face and Player 2 the right. Pose matches, then points and active completion time decide challenges.',gestures:['tap','pinch','rotate']},
 monster:{title:'Monster Me!',objective:'Create an original monster, give it your voice and animate it with your own expressions.',controls:'Customize the parts and colors. Enable the camera to smile, blink, open your mouth and tilt. Record short voices, trim them and choose real voice effects.',win:'Create freely or copy the expression/voice challenge. Mimic asks you to watch and repeat a sequence. Talent Show captures your actual monster performance.',score:'Only live tracked expression or measured microphone challenges earn ranked points. Touch expression previews and creative work are unranked.',rules:'Save the monster before attaching voices. Calibrate a neutral face and use comfortable speaking volume. Save/export keeps your character and recordings locally.',duo:'Face-Off uses alternating turns with the same camera, prompts and difficulty. Correct matches, points and active time decide the winner. Character creation is cooperative.',gestures:['tap','look','listen']},
 zoo:{title:'My Noisy Zoo',objective:'Record your own ridiculous animal sounds, earn zoo coins from their calls and build a living zoo.',controls:'Tap an animal, then Record its voice. Preview/trim/effect the real recording and accept it. Adopt animals, place habitats, drag decorations and pet animals by rubbing.',win:'Grow your zoo, unlock regions, upgrade habitats and complete discoveries. Creative Zoo is a separate unlimited sandbox.',score:'Voiced animal calls earn coins; petting, feeding and objective activities also reward you. Sound Guessing and Choir Battle have separate accuracy/timing records.',rules:'Aquatic animals need water habitats; other animals need land habitats. The microphone is only used after Record. Calls are volume-limited and spaced. Save/export backups keep your recordings.',duo:'Join the optional family zoo intentionally; personal zoos stay separate. Contributions keep each profile’s name. Sound Guessing and rhythm battles use alternating turns and objective scores.',gestures:['tap','drag','listen']},
 bugs:{title:'Bug Squash',objective:'Find the ladybugs that match the large color AND symbol prompt.',controls:'Tap matching bugs. Watch the prompt and listen for the color-change sound.',win:'Build your highest score before the 60-second round ends.',score:'Correct taps earn points and streak bonuses. Reaction times begin when a valid target appears.',rules:'Wrong colors cost points and break your streak. Higher difficulties add more, smaller, faster bugs.',duo:'Play simultaneously: Player 1 on the left, Player 2 on the right. Highest score wins.',gestures:['tap','look','listen']},
 balloons:{title:'Balloon Mayhem',objective:'Pop the drifting balloons while avoiding spiky danger balloons.',controls:'Tap a balloon to pop it. Armored balloons need several taps.',win:'Earn the highest score before time runs out.',score:'Gold balloons and accurate streaks earn more. Time balloons add seconds; mystery balloons change the action.',rules:'Spiky balloons penalize you. In Learning mode, follow the displayed color, number or arithmetic prompt.',duo:'Both players pop on separate sides at the same time. Highest score wins.',gestures:['tap','look','tap']},
 cafe:{title:'Monster Café',objective:'Serve each monster the exact recipe shown on its order card.',controls:'Select a customer. Tap or drag ingredients onto the plate. Tap plated ingredients to remove them, then press Serve.',win:'Serve as many correct orders as possible during your 90-second shift.',score:'Correct recipes and consecutive perfect orders earn points and multipliers.',rules:'Match quantities. Stack ingredients in the displayed order when requested. Wrong recipes and expired orders hurt your result.',duo:'Players take turns with identical recipes and conditions. Highest score after both shifts wins.',gestures:['tap','drag','tap']},
 battle:{title:'Two-Player Tap Battle',objective:'Follow the current skill challenge: signals, moving targets, memory, color, accuracy or survival.',controls:'Tap only the requested target on your side. Wait for the GO cue in reaction challenges.',win:'Win more rounds than your opponent in the chosen match length.',score:'Valid accurate responses earn points. Skill Medley rotates through six challenges.',rules:'Early, wrong and repeated taps are penalized. Watch lives and the changing challenge prompt.',duo:'Player 1 uses the left board; Player 2 uses the right. Play simultaneously. Rounds won decide the match.',gestures:['look','tap','wait']},
 gravity:{title:'Gravity Chaos',objective:'Guide the energy ball into the glowing goal using gravity and the environment.',controls:'Swipe empty space up, down, left or right. Drag platforms; use two fingers to rotate marked platforms. Tap switches and bumpers.',win:'Collect required gold orbs, activate required switches, then reach the goal. Survival mode rewards staying alive.',score:'Collect bonus orbs, finish quickly and use fewer gravity changes and retries.',rules:'Hazards reset the ball at its checkpoint. Some later difficulties limit gravity changes. Draw ramps only in marked zones; hold SAFETY to suppress eligible hazards.',duo:'Use independent boards: Player 1 left, Player 2 right. Race compares finishes/time; Orb Challenge compares orbs; Survival compares survival. Best-of-five needs three round wins.',gestures:['swipe','drag','rotate']},
 slime:{title:'Slime Lab',objective:'Sling your slime to the exit, collecting the required gold orbs.',controls:'Grab the slime, pull BACK and release to launch in the opposite direction. The center stays anchored while pulling. Two fingers can stretch it.',win:'Collect gold orbs and enter the exit. Later courses also need both pressure pads and a merged slime.',score:'Faster clears, collected orbs and fewer retries improve your score and stars.',rules:'Pulling cannot carry the slime. Split small blobs for narrow paths or separate pads, then merge. Hazards cost retries; Restart gives a fresh attempt.',duo:'Race simultaneously on identical independent courses. Player 1 left, Player 2 right. A clear beats an unfinished run; faster clears win.',gestures:['pull','release','pinch']},
 dentist:{title:'Monster Dentist',objective:'Complete every marked treatment and give your monster a healthy smile.',controls:'Choose the matching tool. Scrub or polish back and forth, hold to fill, trace to pick, pull loose teeth along their arrows, or drag in a new tooth and align it.',win:'Treat all teeth correctly before the active-treatment clock runs out.',score:'Correct treatments, accuracy and faster completion improve your result.',rules:'Each tooth shows its required treatment. Wrong tools or gestures count as mistakes. Reactions never block the teeth.',duo:'Players take turns treating identical patients. Completion and accuracy come before time. The clock stays stopped during handoff.',gestures:['rub','trace','rotate']},
 ninja:{title:'Shadow Ninjas',objective:'Collect gold scrolls and sneak into the exit without being spotted.',controls:'Swipe to dash. Hold the shield for protection. Use the jump and short teleport tools when available.',win:'Collect required scrolls and activate gold switches or pressure pads before reaching the exit.',score:'Quick escapes, scrolls and fewer detections earn better scores and stars.',rules:'Watch patrol warnings and hazards. Shields and teleports use finite energy. Retry after a detection without losing older records.',duo:'Both players race simultaneously on identical independent courses. Player 1 left, Player 2 right. Completion wins, then faster time.',gestures:['swipe','hold','look']},
 circuit:{title:'Circuit Rush',objective:'Power every circuit by connecting matching letters and colors.',controls:'Drag from a solid source to its matching ring. Tap switches and rotators before routing through them. Use Undo to revise a wire.',win:'Complete all circuits. Marathon moves through several boards.',score:'Fewer mistakes and faster completed boards earn more points.',rules:'Wires cannot cross except on bridges. Gates and arrows restrict routes; Expert sources must power in letter order. Reset clears wires, but keeps time and mistakes.',duo:'Play simultaneously on identical independent boards. Speed Race prioritizes completion/time; Accuracy prioritizes mistakes; Marathon compares boards and performance.',gestures:['drag','tap','look']},
 face:{title:'Feed the Face',objective:'Feed the floating face the food it currently requests.',controls:'Choose food in your tray, then TAP ahead of the glowing mouth to shoot. Lead the moving head.',win:'Classic/Frenzy: score before time ends. Target: land seven feeds. Survival: keep feeding before six misses.',score:'Correct mouth hits and combos earn points. Points decide a match, then feeds and accuracy.',rules:'Wrong food costs points and causes angry eyebrows. Requests are judged when you launch, so food already flying stays fair. Hits outside the mouth miss.',duo:'Player 1 shoots from the left half; Player 2 from the right. Each has an independent food tray. Both shoot simultaneously at the same face.',gestures:['tap','look','tap']},
 castle:{title:'Castle Creator',objective:'Build a supported castle, protect its king and repel the siege.',controls:'Choose a category and part, then tap to place; drag to move. Foot soldiers march left through open gates or over low walls. Enemy defeats permanently unlock equipment. Use rotate, duplicate, materials, Undo/Redo and Pan/Zoom. Tap an existing object to inspect it; upgrade during construction. Tap enemies within the king’s short range to fire his modest royal star. Other weapons defend automatically.',win:'Survive the required waves with your king alive. Challenges also restrict budget and king damage. Creative building is untimed.',score:'Defeat enemies, inflict damage, preserve your castle and survive more waves.',rules:'Build inside your budget with no overlaps or unsupported pieces. Fallen supports release physical debris. Repairs, traps and reinforcements have limits. Cleared assaults stop the clock for construction, restore surviving objects to their deployment positions at full upgraded health, heal the living king, add gold and one repair, and show the next exact enemy count. Press Start Assault when ready; new unlocks are available immediately.',duo:'Castle Clash: players build equal-budget castles in turns, then attack the other design with equal resources. Damage and surviving objectives decide. Co-op shares one defense.',gestures:['drag','rotate','tap']},
 buddy:{title:'Buddy Mayhem',objective:'Experiment with Pogo’s soft-suit ragdoll or complete the chosen physics challenge.',controls:'Grab a limb, drag and release to fling. Different fingers can hold different limbs. Select a gadget, then tap the room to activate it.',win:'Launch: hit every ring. Bounce: chain eight impacts. Combo: use six gadgets and hit two rings. Target: shoot all rings. Puzzle: hit three rings using two gadgets.',score:'Targets, impact combos, gadget variety and completed challenges earn points and coins.',rules:'Release Pogo to score launch targets. Target Practice uses foam/balls/water shots. Sandbox is unranked; unlock gadgets, costumes and rooms with earned coins.',duo:'Players take alternating turns with identical conditions and equipment. Compare completion, score, mistakes and time. Best-of-three needs two wins; best-of-five needs three.',gestures:['drag','release','tap']},
 doodle:{title:'Doodle Defenders',objective:'Draw defenses that keep doodle monsters away from HOME.',controls:'Line = wall, circle = shield, triangle = turret, zigzag = shock, spiral = slow, star = temporary power. Use select-and-place if you prefer.',win:'Defend HOME through every wave. Endless lasts until HOME falls; Creative sends waves only when requested.',score:'Stop enemies, protect HOME and complete waves. Upgrade defenses with ink.',rules:'Larger drawings cost more ink. Ink regenerates; unclear shapes cost nothing. Enemies can break walls and shields; flyers bypass walls. Undo removes your latest defense.',duo:'Competitive: Player 1 left, Player 2 right, equivalent waves on independent boards. Completion, points, mistakes and time decide the winner. Co-op: draw together on one board, with each pointer keeping its player’s ink color.',gestures:['draw','tap','look']},
 robot:{title:'Robot Repair Shop',objective:'Find the faults, repair the actual components and safely reassemble your robot.',controls:'Scan components. Rotate screws/wrench; drag parts and batteries; connect matching wire terminals; trace circuits; scrub dirty sensors.',win:'Fix all faults, close the panel, refasten all screws and complete three interactive tests. Diagnosis mode instead verifies your scans.',score:'Correct repairs or diagnosis earn points. Fewer mistakes and faster correct work improve your result.',rules:'Loosen panel screws before opening. Disconnect motors before replacing them; reconnect wires afterward. Testing fails if repairs or assembly are incomplete.',duo:'Players repair identical robots in alternating turns. Correctness comes first, then fewer mistakes and faster time. Handoff is untimed.',gestures:['rotate','drag','trace']},
 wars:{title:'Wobbly Wars',objective:'Deploy a balanced army, then watch fully animated 3D battles. Solo has 20 campaign challenges, random armies, sandbox and endless reinforcements.',controls:'Tap an illustrated troop card, then tap your colored deployment zone to purchase and place it. Swipe the roster to see more troops. Drag placed units to reposition; tap one then Remove Selected to refund it. Camera mode: drag to orbit, pinch or use + / − to zoom. Start Battle begins automatic combat.',win:'Defeat every opposing unit. A 35-second period without damage or a 150-second battle is a draw. Versus can use Best of 3 or Best of 5. Endless victories return to deployment for reinforcements.',score:'Defeated units, survivors, damage and victory earn points. Solo sandbox is unranked. New 3D records and older classic results remain separate; saved armies remain compatible.',rules:'Respect costs, unit caps, faction restrictions, spacing and colored zones. Shields block from the front; spears have reach; healers restore allies with bolts; ranged shots can hit obstacles. Pause stops combat and physics. Low, Medium and High graphics are available.',duo:'Versus: Player 1 builds blue on the left; Player 2 builds red on the right with equal budgets. Co-op: both build blue, Player 1 in the far half and Player 2 in the near half, sharing the budget equally against red AI. Supported multitouch allows independent deployment; mouse devices alternate deployment turns. Both press Ready before Start Battle.',gestures:['tap','drag','look']},
 build:{title:'Build & Smash',objective:'Aim at supports and cause a chain reaction that brings down the structure.',controls:'Choose a projectile, pull the sling ball BACK and release. Use a projectile’s Special after launch when available. Build Mode lets you place, move and edit pieces.',win:'Break at least 60% for one star, 85% for two, and every block for three. A star unlocks the next campaign level.',score:'Only impact-broken blocks count. Fewer shots, destruction and completion time improve your result.',rules:'Respect the shot budget and three-minute turn limit. Wait for a shot to settle or use Next Shot. Saved family levels keep their original builder; custom scores award no arcade XP.',duo:'Take turns on identical structures with identical shots. Most Blocks compares destruction, shots and time. Fastest Demolition prioritizes a full clear, then time.',gestures:['pull','release','tap']},
 paint:{title:'Creative Studio',objective:'Create your own picture with brushes, shapes, original stickers and photos.',controls:'Choose a tool and color, then draw. Move selects layers; drag layers, or use two fingers to resize and rotate. Undo/Redo helps you experiment.',win:'There is no timer or losing condition. Finish a creation you want to keep.',score:'Creative milestones earn achievements; there is no competitive high score.',rules:'Save Art stores editable projects. Export downloads an image. Save before leaving to keep changes; photos stay on this device.',duo:'Enable Create Together. Player 1 starts strokes on the left, Player 2 on the right, with separate tool/color settings. Share one canvas cooperatively.',gestures:['draw','pinch','rotate']},
 beat:{title:'Beat Lab',objective:'Make a beat using live pads, custom sounds and sequenced patterns.',controls:'Tap pads to play. Toggle sequencer steps, then press Play. Edit a pad to trim/import sound, change pitch or volume; hold a looping pad to sustain it.',win:'Create freely, record a performance and save or export your music.',score:'Creative milestones earn achievements. Beat Battle compares timing accuracy on identical rhythm patterns.',rules:'BPM sets the beat; pitch changes a sample’s speed/length. Save Project keeps editable sounds and patterns. Record captures your performance; Export creates an MP3.',duo:'Use 2-Player Battle for alternating timing challenges. Both receive the same rhythm. The more accurate performance wins; ordinary music-making is shared creative play.',gestures:['tap','hold','listen']}
};
const GESTURES={tap:['TAP','M30 44v-15a5 5 0 0 1 10 0v9l9-2 7 10-7 12H34l-12-14 5-4 6 6M30 16l-3-5m16 5 4-5m-12 3V6'],drag:['DRAG','M10 30h46m-8-8 8 8-8 8M26 49V31a5 5 0 0 1 10 0v9l10-2 7 12-7 10H30l-12-14'],swipe:['SWIPE','M9 17h47m-9-8 9 8-9 8M30 52V33a5 5 0 0 1 10 0v9l9-2 7 12-7 9H34l-12-13'],rotate:['ROTATE','M12 30a21 21 0 1 1 40 0M45 26l7 7 7-7M22 58V40a5 5 0 0 1 10 0v8l11-2 5 10'],pull:['PULL BACK','M12 15l9 12-9 13m44-25L45 27l11 13M21 27h24M32 58V39a5 5 0 0 1 10 0v8'],release:['RELEASE','M11 23l15-9m14 0 15 9M29 9V2m-8 45 11-17a5 5 0 0 1 8 5l-5 10 10 5-6 11H24l-9-9'],pinch:['PINCH','M7 10l14 14M7 10v10m0-10h10m40 0L43 24m14-14v10m0-10H47M20 57V36a5 5 0 0 1 10 0v12m13 9V36a5 5 0 0 1 10 0v12'],draw:['DRAW','M10 52c12-30 20 12 31-14M38 31l13-20 7 5-13 20-10 6z'],trace:['TRACE','M7 44l13-17 13 17 13-17 13 17M12 12h40'],rub:['SCRUB','M8 14h48m-7-7 7 7-7 7M15 7l-7 7 7 7M24 56V34a5 5 0 0 1 10 0v10l12-2 7 13'],hold:['HOLD','M13 17a23 23 0 0 1 38 0M28 55V27a5 5 0 0 1 10 0v13l11-2 7 13-7 10H32'],look:['WATCH','M5 31q27-30 54 0-27 30-54 0m27-11a11 11 0 1 0 0 22 11 11 0 1 0 0-22'],listen:['LISTEN','M11 25h10l12-11v36L21 39H11zm31-4q13 11 0 22m8-28q20 17 0 34'],wait:['WAIT FOR GO','M13 7h38M13 57h38M18 7v11l25 28v11M46 7v11L21 46v11']};
export function instructionContent(game,context={}){const data=GAME_INSTRUCTIONS[game];if(!data)throw Error('Missing instructions for '+game);const c={...data};if(game==='limit'&&context.mode==='suite'){Object.assign(c,{objective:'Measure five repeatable workloads: Forest environment, Castle lighting, Arena combat, Chamber physics/particles and combined Chamber load.',controls:'Automatic scripted actors and fixed camera paths. No movement input is needed. Pause, resize, help, settings or losing focus cancels the run; restart intentionally afterward.',win:'Each scene loads, warms for three seconds and records eight seconds of actual frame times. Loading and warm-up are excluded. A full result saves only after all five scenarios finish.',score:'No points or adventure progress. Results include measured average/1% low FPS, frame-time percentiles and raw samples; export JSON or CSV and compare matching editions/settings.',rules:'Settings remain fixed. GPU readings are unavailable unless reported; JavaScript heap is not RAM or VRAM. Software results do not predict Windows GPU performance. Seeded 60 Hz scripted rules use a 100 ms per-frame catch-up cap; physics and browser scheduling can vary.',duo:'This is an automatic device benchmark, not a multiplayer adventure. Existing solo/co-op adventure modes are unchanged.'});}if(game==='limit'&&context.mode==='journey'){Object.assign(c,{objective:'Complete the connected Living Forest, Ancient Castle, Crown Arena and Chaos Chamber. Both explorers must reach each exit.',win:'Restore each area’s marked lights/seals, defeat its objective guardians, use the exit lever and bring every explorer through. Press Continue between areas. Open Castle side-room doors with Interact. The Crown Warden adds ranged spells below half health. Stabilize both Chamber reactors to open the return portal.',score:'Only a completed four-area expedition saves points. Its separate edition starts at 6400 points, subtracts 100 per water recovery and 150 per combat recovery, and adds up to 900 points for active play under 900 seconds; minimum 1000. No intermediate or abandoned score. Forest-only results remain separate.',rules:data.rules+' Unfinished expeditions restart from the Forest. In the Chamber, optional load controls have safe caps and an immediate reset; extra test enemies never lock the exit. Demo pulses cause no damage. This interactive workload is not the formal multi-zone benchmark.'});}if(game==='wars'&&context.edition==='classic'){Object.assign(c,{objective:'Build a balanced army and watch the preserved classic 2D physics battle.',controls:'Select a unit and tap to deploy. Drag units to reposition, remove or Undo to refund. Pan/Zoom changes your view. Start Battle begins automatic combat.',win:'Defeat the opposing army. Prolonged stalemates are draws. Endless lets you reinforce survivors.',rules:'Stay within the displayed budget, deployment area, unit cap and faction restriction. Pause stops the simulation. Classic and new 3D records remain separate.',duo:'Player 1 prepares the left army, then Player 2 prepares the right army with an equal budget. After both are ready the armies fight automatically.'});}if(game==='spelling'){const controls={bee:'Listen to the word, practice it on the board, then type the full spelling and press Submit.',builder:'Tap letter tiles to assemble the word, or drag tiles into position. Tap a placed tile to remove it. Distractor letters do not all belong. Submit the assembled spelling.',missing:'Read the partial word, listen to its pronunciation, then type ONLY the missing letters in order. The whiteboard can hold your full-word practice.',sprint:'Listen and type as many correct spellings as you can. Submit, read feedback and press Next. Speed adds up to 20 points. The clock stops during Pause or Help.',survival:'Listen, practice and type. Every mistake costs one of three hearts. Survive and build your streak; the word patterns become more complex within your selected pool.'};c.controls=controls[context.mode]+' Touchscreen keys and physical keyboards work. Drawing is practice only; pen, eraser, undo and clear never submit an answer.';c.win=context.mode==='survival'?'Keep spelling until three hearts are lost or this adventure’s word pool is exhausted.':context.mode==='sprint'&&!context.untimed?'Score as many points as possible in '+(context.seconds||60)+' active seconds.':'Finish '+(context.words||10)+' submitted words. Read each correction, then choose Next Word.';}if(game==='zoo'){const activities={'Sound Guessing':{objective:'Identify your animals by listening to their own saved recordings.',controls:'Tap Listen to begin a turn, hear the personal recording, then tap the matching illustrated animal.',win:'Answer five questions per player. Most correct answers wins; lower response time breaks a tie.',score:'Each correct answer earns 200 points and eight zoo coins.',rules:'Record at least two animal voices first. Two players take alternating turns. No microphone is opened during this listening game.'},'Choir Rhythm Battle':{objective:'Listen to a six-animal rhythm, then repeat its order and timing.',controls:'Tap Listen, then Match. After the six-call demonstration, tap the pictured animal on each displayed beat.',win:'Correct animals and accurate timing earn the highest total. Two players receive the same sequence and tempo.',score:'Correct beats earn 200 points plus timing bonuses; wrong taps lose 25 points.',rules:'The demonstration uses short excerpts of your actual recordings. Comfortable listening only; no microphone or subjective voice judging.'},'Animal Choir':{objective:'Arrange your animals’ personal voices into a silly musical sequence.',controls:'Tap animals to add them. Tap sequence chips to remove them. Set the tempo, play, stop, save or export a WAV performance.',win:'Create a performance you want to keep. A choir with four distinct animals unlocks a discovery.',score:'Creative activity is unranked. The first four-animal choir earns a small zoo reward.',rules:'Only animals with personal recordings join this choir. Up to 16 calls fit in a saved sequence. Leaving stops playback.'},'Animal Talent Show':{objective:'Create an animated performance starring one of your voiced animals.',controls:'Choose a star and animation. Tap Perform to hear its voice, or Record to capture an eight-second animated show.',win:'Name, save and export a performance from your local gallery.',score:'This creative show has no ranked score or subjective judging.',rules:'The video includes the animal’s saved voice; this activity never opens the microphone. Export uses the real supported video format.'}};Object.assign(c,activities[context.mode]||{});}if(game==='monster'&&context.mode==='mimic'){c.objective='Watch a short sequence of monster expressions, then copy it with your face.';c.controls='Enable your camera, press Start Challenge, watch every prompt, then repeat the same sequence. Hold each expression until it registers.';c.rules='The watch phase is untimed for scoring input. Manual touch previews never score. Face-Off uses identical sequences on alternating turns.';}if(game==='monster'&&context.mode==='voice'){c.objective='Match five comfortable microphone challenges using volume and pitch.';c.controls='Enable the microphone, then Start Challenge. Follow the soft, steady, low-note, high-note and quiet-sound prompts. Hold within the target range.';c.win='Complete five measured targets within 45 seconds. Two players take equivalent alternating turns.';c.score='Each held target earns 250 points. We measure volume, pitch and timing, never how funny a voice sounds.';c.rules='Do not shout. Adjust sensitivity or move the microphone closer. The camera is unnecessary for this activity.';}if(game==='spelling'){c.controls+=' Repeat Word and Say It Slowly speak only the word. Setup and paused Settings let you choose and preview up to three available female American English voices.';if(context.layout==='turns'){if(context.mode==='sprint')c.controls=c.controls.replace('Listen and type as many correct spellings as you can. Submit, read feedback and press Next.','Listen, type one answer and submit before this word’s timer ends. Read the feedback, then choose Next Player.');c.win='Each player completes '+(context.words||10)+' spelling challenges ('+((context.words||10)*2)+' turns together). Read your feedback, then press Next Player. The highest adjusted score wins; matching scores use accuracy, then tie.';c.duo='Player 1 and Player 2 alternate after every submitted word. Read your feedback, press Next Player, then pass the screen. The next player presses Ready before their word appears or is spoken. Each player completes '+(context.words||10)+' words with their own writing, history and streak.';c.score='Correct answers, no-hint bonuses and streaks earn base points. Difficulty weights are Niko ×1, Roxy ×1.25 and Kelly ×1.5. The highest adjusted score wins; accuracy breaks a tie.';c.rules='Your writing, history and streak belong to you. Auto-Clear only clears your own board. Feedback and Ready screens stop the clock. Mastery needs three correct answers without hints in separate adventures.'+(context.mode==='sprint'&&!context.untimed?' Each word has '+(context.seconds||60)+' active seconds; a timeout counts as an incorrect answer.':context.mode==='survival'?' Hearts track mistakes, but both players finish their selected word count.':'');}}const unranked=(context.players?.length||1)<2&&['creative','sandbox'].includes(context.mode);if(unranked)c.score='Experiment freely with the displayed session score. Creative sessions award no competitive records or arcade XP.';if(game==='buddy'&&context.mode==='sandbox')c.win='Explore freely with no timer. Press Finish Session when you are done. Sandbox earns no ranked coins or competitive records.';if(game==='buddy'&&context.mode==='sandbox')c.score='Targets and impact combos display a session score. Sandbox awards no coins, arcade XP or competitive records.';if(game==='robot'&&context.mode==='diagnosis'){c.objective='Use the scanner to identify every faulty component.';c.win='Scan all faults, then press Test to verify the diagnosis. This mode does not count as a full repair.';}if(game==='castle'&&['creative','sandbox'].includes(context.mode))c.win=context.mode==='creative'?'Build freely with unlimited resources and no enemy attacks. Save your castle or finish when ready.':'Experiment with unlimited building resources, then start an attack to test the castle.';return c;}
let instructionSession=null;
export function selectInstructionSession(game){if(instructionSession?.game!==game)instructionSession={game,acknowledged:false};}
export function endInstructionSession(){instructionSession=null;}
export function createInstructionGate({game,onBack,onReview=()=>{}}){
 let dialog=null,disposed=false,launchFrame=0,help=null,lastContext=null,reviewClose=null;const state=instructionSession?.game===game?instructionSession:{acknowledged:false};
 function ensureHelp(){if(help||disposed)return;help=document.createElement('button');help.className='game-instruction-help';help.textContent='? HOW TO PLAY';help.setAttribute('aria-label','Review '+GAME_INSTRUCTIONS[game].title+' instructions');help.onclick=()=>api.review();document.body.append(help);}
 function remove(){if(!dialog)return;dialog.close();dialog.remove();dialog=null;}
 const api={get pending(){return !!dialog||!!launchFrame;},get acknowledged(){return state.acknowledged;},review(){if(!lastContext||disposed||dialog||launchFrame)return;const result=onReview();if(result===false)return;reviewClose=typeof result==='function'?result:null;api.show(lastContext,()=>{reviewClose?.();reviewClose=null;},true);},show(context,start=()=>{},review=false){if(disposed||dialog||launchFrame)return;lastContext=context;if(state.acknowledged&&!review){ensureHelp();launchFrame=requestAnimationFrame(()=>{launchFrame=0;if(!disposed)start();});return;}const c=instructionContent(game,context),names=context.players||[],two=names.length>1||context.coop,unranked=!two&&['creative','sandbox'].includes(context.mode);
 dialog=document.createElement('dialog');dialog.className='how-to-play'+(game==='limit'?' limit-how-to':game==='air'?' air-how-to':game==='spelling'?' spelling-how-to':'');dialog.setAttribute('aria-labelledby','howToTitle');dialog.setAttribute('aria-describedby','howToObjective');dialog.innerHTML=`<div class="how-to-panel"><header class="how-to-heading"><div><span class="eyebrow">HOW TO PLAY · YOUR NEXT ADVENTURE</span><h2 id="howToTitle">${esc(c.title)}</h2><p>${esc(context.difficulty||'CREATIVE PLAY')}${context.modeLabel?' · '+esc(context.modeLabel):''}</p></div><div class="how-to-art" aria-hidden="true">${game==='limit'?limitCover():game==='gladiator'?gladiatorCover():game==='math'?mathCover():game==='spelling'?spellingCover():game==='air'?airSliceDemoArt():['funny','monster','zoo'].includes(game)?mediaCoverArt(game):game==='face'?'<img src="assets/face-closed.png" alt="">':coverArt(game)}</div></header><div class="how-to-objective" id="howToObjective"><span>YOUR MISSION</span><p>${esc(c.objective)}</p></div><div class="how-to-gestures" aria-label="Touch gestures">${c.gestures.map(id=>{const [label,path]=GESTURES[id];return `<div><svg viewBox="0 0 64 64" aria-hidden="true"><path d="${path}"/></svg><b>${label}</b></div>`;}).join('')}</div><div class="how-to-rules">${[['TOUCH CONTROLS',c.controls],['HOW TO WIN',c.win],['HOW TO SCORE',c.score],['KNOW THE RULES',c.rules]].map(([title,text],i)=>`<section><span class="how-to-number">${i+1}</span><div><h3>${title}</h3><p>${esc(text)}</p></div></section>`).join('')}</div><div class="how-to-players"><strong>${names.map((name,i)=>`PLAYER ${i+1} · ${esc(name)}`).join(' <span>✦</span> ')||'YOUR CREATIVE SESSION'}</strong><p>${esc(two?c.duo:game==='paint'||game==='beat'?c.duo:unranked?'Creative session · experiment freely. No competitive record or arcade XP is awarded.':'Single player · unlimited new attempts. '+(context.learn?'Learning mode: follow the displayed matching/counting prompt.':'Completed results save to your selected profile.'))}</p></div><footer><button class="btn secondary" data-instructions-back>${review?'CLOSE HELP':'← GAME SELECTION'}</button><button class="btn primary" data-instructions-start autofocus>${review?'BACK TO GAME':game==='spelling'?"GOT IT — LET’S PLAY!":game==='air'?'GOT IT! — LET’S SLICE':'GOT IT — START GAME'}</button></footer><small class="how-to-stopped">GAMEPLAY IS STOPPED · THE CLOCK STARTS AFTER YOU ACKNOWLEDGE</small></div>`;
 for(const type of ['pointerdown','pointerup','click'])dialog.addEventListener(type,e=>e.stopPropagation());dialog.addEventListener('cancel',e=>e.preventDefault());
 dialog.querySelector('[data-instructions-start]').onclick=e=>{e.stopPropagation();if(!dialog||disposed)return;remove();state.acknowledged=true;ensureHelp();launchFrame=requestAnimationFrame(()=>{launchFrame=0;if(!disposed)start();});};dialog.querySelector('[data-instructions-back]').onclick=e=>{e.stopPropagation();remove();if(review){reviewClose?.();reviewClose=null;}else onBack();};document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-instructions-start]').focus();
 },dispose(){disposed=true;if(launchFrame)cancelAnimationFrame(launchFrame);launchFrame=0;remove();help?.remove();reviewClose?.();reviewClose=null;}};return api;
}
